WITH RECURSIVE seq AS (
  SELECT 1 AS n
  UNION ALL
  SELECT n + 1 FROM seq WHERE n < 5000
)
SELECT COUNT(*) FROM seq;

SELECT customer_id, id, total,
       LAST_VALUE(total) OVER (
         PARTITION BY customer_id ORDER BY created_at
       ) AS latest_total
FROM orders;

CREATE VIEW city_counts AS
  SELECT city, COUNT(*) AS n
  FROM customers
  GROUP BY city;

UPDATE city_counts SET city = 'Bengaluru' WHERE city = 'Bangalore';

